import { Box, Flex, IconButton, Text } from "@chakra-ui/react";
import React, { forwardRef } from "react";
import type { ConversationEvent, ConversationEventAction } from "../../../types";
import { Icon } from "../../../Icon";
import { ChevronDown, ChevronUp, Wrench } from "../../../Icon/icons";
import { ConversationEventActionButton } from "../../ConversationEventActionButton";
import { useConversationLogSx } from "../useConversationLogSx";
import { ErrorDot } from "./ErrorDot";

interface ToolRunLogRowProps {
  event: ConversationEvent;
  isSelected: boolean;
  prefix: string;
  suffix: string;
  conversationEventActions?: ConversationEventAction[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  onKeyDown?: (e: React.KeyboardEvent<HTMLDivElement>) => void;
  expanded?: boolean;
  onToggleExpand?: () => void;
}

export const ToolRunLogRow = forwardRef<HTMLDivElement | null, ToolRunLogRowProps>(
  (props: ToolRunLogRowProps, ref) => {
    const {
      event,
      isSelected = false,
      conversationEventActions,
      prefix,
      suffix,
      onClick,
      onKeyDown,
      expanded,
      onToggleExpand,
      ...otherProps
    } = props;
    const { hoverableContainerSx, baseMessageSx, iconSx } = useConversationLogSx(isSelected);
    const [isHovered, setIsHovered] = React.useState(false);

    const toolName = event.metadata?.tool_name ?? event.name ?? "tool";
    const isError = event.metadata?.tool_is_error === true;

    return (
      <Flex
        ref={ref}
        tabIndex={0}
        role="button"
        position="relative"
        cursor="pointer"
        css={hoverableContainerSx}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        onClick={onClick}
        onKeyDown={onKeyDown}
        {...otherProps}
      >
        {isHovered && (
          <ConversationEventActionButton event={event} actions={conversationEventActions} />
        )}
        <Box css={baseMessageSx}>
          <Icon icon={Wrench} style={iconSx} />
          <Text textStyle="xs" lineClamp={2} wordBreak="break-all" variant="muted">
            {prefix}
            <Text as="span" fontWeight="medium" variant="muted">
              {toolName}
            </Text>
            {suffix}
          </Text>
          {isError && <ErrorDot />}
          {onToggleExpand ? (
            <IconButton
              aria-label={expanded ? "Collapse tool call events" : "Expand tool call events"}
              size="2xs"
              variant="ghost"
              colorPalette="gray"
              data-testid="tool-call-toggle"
              onClick={(clickEvent) => {
                clickEvent.stopPropagation();
                onToggleExpand();
              }}
            >
              <Icon icon={expanded ? ChevronUp : ChevronDown} size="sm" />
            </IconButton>
          ) : null}
        </Box>
      </Flex>
    );
  },
);

ToolRunLogRow.displayName = "ToolRunLogRow";
